import static org.lwjgl.opengl.GL33C.*;import org.lwjgl.system.MemoryUtil;import java.nio.*;
/** GPU columns cover the complete world; a finer ring surrounds the exact vanilla block mesh. */
final class WholeMapBlocks implements AutoCloseable {
 int program,vao,heights,colors,n,treeProgram,treeBuffer,treeTexture,treeCount;long columns;
 record Level(int step,int x,int z,int grid){}
 static Level far(int size){int step=Math.max(1,Integer.highestOneBit(Math.max(1,(size+511)/512)-1)<<1);return new Level(step,0,0,(size+step-1)/step);}
 static Level middle(int size,double x,double z){int step=Math.max(1,far(size).step()/4),span=Math.min(size,step*384),ox=Math.max(0,Math.min(size-span,(int)Math.floor((x-span/2.)/step)*step)),oz=Math.max(0,Math.min(size-span,(int)Math.floor((z-span/2.)/step)*step));return new Level(step,ox,oz,(span+step-1)/step);}
 static final String VERTEX="""
 #version 330 core
 uniform usampler2D heights;uniform sampler2D colors;uniform vec3 eye,right,up,forward;uniform float aspect,farPlane;uniform int worldSize,step,grid,lod;uniform ivec2 origin;
 out vec3 color;out vec2 worldXZ;
 float top(ivec2 p){uvec2 h=texelFetch(heights,clamp(p,ivec2(0),ivec2(worldSize-1))/(1<<lod),lod).rg;return float(max(h.x,h.y))-64.0;}
 void main(){int cell=gl_VertexID/30,face=(gl_VertexID%30)/6,k=gl_VertexID%6;ivec2 p=origin+ivec2(cell%grid,cell/grid)*step;float s=float(step);vec2 c=vec2(k==1||k==2||k==4?1:0,k==2||k==4||k==5?1:0);float h=top(p+ivec2(step/2));vec3 v;float shade=1.;
 if(face==0)v=vec3(vec2(p)+c*s,h).xzy;
 else {ivec2 neighbor=p;vec2 edge;
 if(face==1){edge=vec2(p)+vec2(0,c.x*s);neighbor.x-=step;shade=.68;}
 else if(face==2){edge=vec2(p)+vec2(s,c.x*s);neighbor.x+=step;shade=.84;}
 else if(face==3){edge=vec2(p)+vec2(c.x*s,0);neighbor.y-=step;shade=.76;}
 else {edge=vec2(p)+vec2(c.x*s,s);neighbor.y+=step;shade=.62;}
 float bottom=top(neighbor+ivec2(step/2));if(any(lessThan(neighbor,ivec2(0)))||any(greaterThanEqual(neighbor,ivec2(worldSize))))bottom=-64.;v=vec3(edge.x,mix(min(h,bottom),h,c.y),edge.y);}
 worldXZ=v.xz;color=vec3(shade);vec3 d=v-eye;vec3 q=vec3(dot(d,right),dot(d,up),-dot(d,forward));float nearPlane=1.,tanHalf=.70020754;gl_Position=vec4(q.x/(tanHalf*aspect),q.y/tanHalf,((farPlane+nearPlane)*q.z+2.*farPlane*nearPlane)/(nearPlane-farPlane),-q.z);}
 """;
 static final String FRAGMENT="""
 #version 330 core
 uniform vec4 hole,detailHole;uniform int worldSize;uniform sampler2D colors;uniform bool terrainTint;in vec3 color;in vec2 worldXZ;out vec4 pixel;
 bool inside(vec4 r){return r.z>0.&&worldXZ.x>=r.x&&worldXZ.y>=r.y&&worldXZ.x<r.x+r.z&&worldXZ.y<r.y+r.w;}
 void main(){if(any(lessThan(worldXZ,vec2(0)))||any(greaterThan(worldXZ,vec2(worldSize)))||inside(hole)||inside(detailHole))discard;pixel=vec4(terrainTint?texture(colors,worldXZ/float(worldSize)).rgb*color:color,1);}
 """;
 static final String TREE_VERTEX="""
 #version 330 core
 uniform samplerBuffer trees;uniform vec3 eye,right,up,forward;uniform float aspect,farPlane;out vec3 color;out vec2 worldXZ;
 void main(){vec4 tree=texelFetch(trees,gl_InstanceID*2);float width=texelFetch(trees,gl_InstanceID*2+1).x;int cube=gl_VertexID/36,face=(gl_VertexID%36)/6,k=gl_VertexID%6;vec2 c=vec2(k==1||k==2||k==4?1:0,k==2||k==4||k==5?1:0);vec3 v;
 if(face==0)v=vec3(c.x,c.y,0);else if(face==1)v=vec3(c.x,c.y,1);else if(face==2)v=vec3(0,c.y,c.x);else if(face==3)v=vec3(1,c.y,c.x);else if(face==4)v=vec3(c.x,1,c.y);else v=vec3(c.x,0,c.y);
 float w=cube==0?1.5:width;float bottom=cube==0?0.:tree.w*.30;float height=cube==0?tree.w*.45:tree.w*.70;v=vec3(tree.x+(v.x-.5)*w,tree.y+bottom+v.y*height,tree.z+(v.z-.5)*w);worldXZ=v.xz;color=(cube==0?vec3(.32,.22,.12):vec3(.20,.34,.16))*(face==4?1.:face==2?.65:.82);vec3 d=v-eye;vec3 q=vec3(dot(d,right),dot(d,up),-dot(d,forward));float nearPlane=1.,tanHalf=.70020754;gl_Position=vec4(q.x/(tanHalf*aspect),q.y/tanHalf,((farPlane+nearPlane)*q.z+2.*farPlane*nearPlane)/(nearPlane-farPlane),-q.z);}
 """;
 WholeMapBlocks(TerraForge.World w){n=w.size;program=GpuTerrainViewer.program(VERTEX,FRAGMENT);vao=glGenVertexArrays();heights=glGenTextures();glBindTexture(GL_TEXTURE_2D,heights);glTexImage2D(GL_TEXTURE_2D,0,GL_RG16UI,n,n,0,GL_RG_INTEGER,GL_UNSIGNED_SHORT,(ByteBuffer)null);params();int maxLod=Integer.numberOfTrailingZeros(far(n).step()),summit=-64;short[] pooled=maxLod>0?new short[(n/2)*(n/2)*2]:null;int rows=Math.min(64,n);ShortBuffer data=MemoryUtil.memAllocShort(n*rows*2);try{for(int z=0;z<n;z+=rows){data.clear();int count=Math.min(rows,n-z);for(int zz=0;zz<count;zz++)for(int x=0;x<n;x++){int h=w.h(x,z+zz)+64,water=w.waterY(x,z+zz)+64;summit=Math.max(summit,h-64);data.put((short)h);data.put((short)water);if(pooled!=null){int i=(((z+zz)/2)*(n/2)+x/2)*2;pooled[i]=(short)Math.max(pooled[i],h);pooled[i+1]=(short)Math.max(pooled[i+1],water);}}data.flip();glTexSubImage2D(GL_TEXTURE_2D,0,0,z,n,count,GL_RG_INTEGER,GL_UNSIGNED_SHORT,data);}}finally{MemoryUtil.memFree(data);}
 int farSummit=summit;for(int lod=1,side=n/2;lod<=maxLod;lod++,side/=2){uploadLevel(lod,side,pooled);if(lod==maxLod){farSummit=-64;for(int i=0;i<pooled.length;i+=2)farSummit=Math.max(farSummit,pooled[i]-64);}else pooled=maxPool(pooled,side);}pooled=null;System.out.println("WHOLE_MAP_PEAK: terrainY="+summit+" farBlocksY="+farSummit);
 int cn=Math.min(n,4096);colors=glGenTextures();glBindTexture(GL_TEXTURE_2D,colors);glTexImage2D(GL_TEXTURE_2D,0,GL_RGBA8,cn,cn,0,GL_RGBA,GL_UNSIGNED_BYTE,(ByteBuffer)null);params();ByteBuffer pixels=MemoryUtil.memAlloc(cn*4*64);try{for(int z=0;z<cn;z+=64){pixels.clear();int count=Math.min(64,cn-z);for(int zz=0;zz<count;zz++)for(int x=0;x<cn;x++){int sample=EnvironmentView.riverSample(w,x,z+zz,cn),wx=sample%n,wz=sample/n;java.awt.Color c=w.waterY(wx,wz)>w.h(wx,wz)?new java.awt.Color(48,92,165):EnvironmentView.surfaceColor(w,wx,wz);pixels.put((byte)c.getRed()).put((byte)c.getGreen()).put((byte)c.getBlue()).put((byte)255);}pixels.flip();glTexSubImage2D(GL_TEXTURE_2D,0,0,z,cn,count,GL_RGBA,GL_UNSIGNED_BYTE,pixels);}}finally{MemoryUtil.memFree(pixels);}treeProgram=GpuTerrainViewer.program(TREE_VERTEX,FRAGMENT);treeCount=w.environment.trees.size();treeBuffer=glGenBuffers();treeTexture=glGenTextures();if(treeCount>0){FloatBuffer trees=MemoryUtil.memAllocFloat(treeCount*8);try{for(var placement:w.environment.trees){var tree=TreeLibrary.catalog().trees().get(placement.tree());trees.put(placement.x()).put(w.h(placement.x(),placement.z())).put(placement.z()).put(tree.height).put(Math.max(3,Math.max(tree.width,tree.length)*.65f)).put(0).put(0).put(0);}trees.flip();glBindBuffer(GL_TEXTURE_BUFFER,treeBuffer);glBufferData(GL_TEXTURE_BUFFER,trees,GL_STATIC_DRAW);glBindTexture(GL_TEXTURE_BUFFER,treeTexture);glTexBuffer(GL_TEXTURE_BUFFER,GL_RGBA32F,treeBuffer);}finally{MemoryUtil.memFree(trees);}}int error=glGetError();if(error!=GL_NO_ERROR)throw new IllegalStateException("Whole-map upload OpenGL "+error);System.out.println("WHOLE_MAP_BLOCKS_READY: "+n+" x "+n+" · complete height field on GPU · distant columns "+far(n).step()+" blocks, finer ring "+middle(n,n/2.,n/2.).step()+" blocks");}
 static short[] maxPool(short[] source,int side){int next=side/2;short[] result=new short[next*next*2];for(int z=0;z<next;z++)for(int x=0;x<next;x++)for(int channel=0;channel<2;channel++){int i=(z*2*side+x*2)*2+channel;result[(z*next+x)*2+channel]=(short)Math.max(Math.max(source[i],source[i+2]),Math.max(source[i+side*2],source[i+side*2+2]));}return result;}
 void uploadLevel(int level,int side,short[] data){glTexImage2D(GL_TEXTURE_2D,level,GL_RG16UI,side,side,0,GL_RG_INTEGER,GL_UNSIGNED_SHORT,(ByteBuffer)null);ShortBuffer row=MemoryUtil.memAllocShort(side*Math.min(64,side)*2);try{for(int z=0;z<side;z+=64){int rows=Math.min(64,side-z);row.clear();row.put(data,z*side*2,rows*side*2).flip();glTexSubImage2D(GL_TEXTURE_2D,level,0,z,side,rows,GL_RG_INTEGER,GL_UNSIGNED_SHORT,row);}}finally{MemoryUtil.memFree(row);}}
 void params(){glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_NEAREST);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_NEAREST);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_S,GL_CLAMP_TO_EDGE);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_T,GL_CLAMP_TO_EDGE);}
 void vec(String key,double x,double y,double z){glUniform3f(glGetUniformLocation(program,key),(float)x,(float)y,(float)z);}
 void draw(double x,double y,double z,double yaw,double pitch,int width,int height,MinecraftMesh.Patch patch){glUseProgram(program);double co=Math.cos(yaw),si=Math.sin(yaw),cp=Math.cos(pitch),sp=Math.sin(pitch);vec("eye",x,y,z);vec("right",co,0,si);vec("forward",si*cp,sp,-co*cp);vec("up",-si*sp,cp,co*sp);glUniform1f(glGetUniformLocation(program,"aspect"),width/(float)height);glUniform1f(glGetUniformLocation(program,"farPlane"),n*5f);glUniform1i(glGetUniformLocation(program,"worldSize"),n);glUniform1i(glGetUniformLocation(program,"terrainTint"),1);glActiveTexture(GL_TEXTURE1);glBindTexture(GL_TEXTURE_2D,heights);glUniform1i(glGetUniformLocation(program,"heights"),1);glActiveTexture(GL_TEXTURE2);glBindTexture(GL_TEXTURE_2D,colors);glUniform1i(glGetUniformLocation(program,"colors"),2);glBindVertexArray(vao);var near=middle(n,x,z);glUniform4f(glGetUniformLocation(program,"detailHole"),patch==null?0:patch.x(),patch==null?0:patch.z(),patch==null?0:patch.side(),patch==null?0:patch.side());glUniform4f(glGetUniformLocation(program,"hole"),near.x(),near.z(),near.grid()*near.step(),near.grid()*near.step());level(far(n));glUniform4f(glGetUniformLocation(program,"hole"),0,0,0,0);level(near);if(treeCount>0){int terrainProgram=program;program=treeProgram;glUseProgram(program);vec("eye",x,y,z);vec("right",co,0,si);vec("forward",si*cp,sp,-co*cp);vec("up",-si*sp,cp,co*sp);glUniform1f(glGetUniformLocation(program,"aspect"),width/(float)height);glUniform1f(glGetUniformLocation(program,"farPlane"),n*5f);glUniform1i(glGetUniformLocation(program,"worldSize"),n);glUniform4f(glGetUniformLocation(program,"hole"),0,0,0,0);glUniform4f(glGetUniformLocation(program,"detailHole"),patch==null?0:patch.x(),patch==null?0:patch.z(),patch==null?0:patch.side(),patch==null?0:patch.side());glActiveTexture(GL_TEXTURE3);glBindTexture(GL_TEXTURE_BUFFER,treeTexture);glUniform1i(glGetUniformLocation(program,"trees"),3);glDrawArraysInstanced(GL_TRIANGLES,0,72,treeCount);program=terrainProgram;}glActiveTexture(GL_TEXTURE0);}
 void level(Level l){glUniform1i(glGetUniformLocation(program,"lod"),Integer.numberOfTrailingZeros(l.step()));glUniform1i(glGetUniformLocation(program,"step"),l.step());glUniform1i(glGetUniformLocation(program,"grid"),l.grid());glUniform2i(glGetUniformLocation(program,"origin"),l.x(),l.z());glDrawArrays(GL_TRIANGLES,0,l.grid()*l.grid()*30);}
 public void close(){glDeleteProgram(program);glDeleteProgram(treeProgram);glDeleteBuffers(treeBuffer);glDeleteTextures(treeTexture);glDeleteVertexArrays(vao);glDeleteTextures(heights);glDeleteTextures(colors);}
}
